from pathlib import Path
import json, html
from urllib.parse import quote
from PIL import Image
ROOT=Path(__file__).resolve().parents[1]
out=ROOT/'vista_previa'
data=json.loads((out/'inventario.json').read_text(encoding='utf-8'))
esc=lambda x:html.escape(str(x))
articles=[]
for r in sorted(data,key=lambda r: (r['archivo']!='ldem_64.tif',r['cuerpo']!='Luna',r['archivo'])):
    name=r['archivo']; dup=r.get('duplicado_de'); ref=next((x for x in data if x['archivo']==dup),r)
    w,h=Image.open(out/r['preview']).size
    facts={'Clasificación':r['cuerpo'],'Contenido':r['tipo'],'Tamaño original':f"{r['bytes']/1024**2:,.2f} MiB"}
    if 'dimensiones' in r:facts['Dimensiones']=' × '.join(map(str,r['dimensiones']))+' px'
    if 'escala_m_por_pixel' in ref:facts['Escala del mapa']=str(int(ref['escala_m_por_pixel'][0]))+' m/píxel'
    if 'resolucion' in ref:facts['Resolución']=ref['resolucion']
    if 'min_max_completo' in ref:facts['Rango almacenado']=' a '.join(f'{x:,.4f}' for x in ref['min_max_completo'])
    if 'vertices' in r:facts.update({'Vértices':f"{r['vertices']:,}",'Caras':f"{r['caras']:,}"})
    caption=ref.get('escala_preview',{}).get('metodo','Superficie superior reconstruida desde los vértices OBJ, muestreada para esta vista. Color por Z; unidades y escala física desconocidas. No es un render de la textura ni de la base de la malla.')
    links=f'<a href="../datos/{quote(name)}">Abrir original</a>'
    if name=='trekOBJ.zip':links+='<a href="modelo/model.obj">OBJ extraído</a><a href="modelo/terrain.mtl">Material MTL</a><a href="modelo/texture.png">Textura PNG</a>'
    extra=''
    if name=='ldem_64.tif':extra='<p class="legend">Escala de color: azul −9 km · verde −5 km · beige 1 km · marrón 6 km · blanco 11 km.</p><a href="ldem_gris.png">Ver mapa de altura en gris</a>'
    if name=='trekOBJ.zip':
        tw,th=Image.open(out/'modelo/texture.png').size
        extra=f'<details><summary>Ver textura original ({tw} × {th} px)</summary><img src="modelo/texture.png" width="{tw}" height="{th}" alt="Textura original incluida en el archivo ZIP" loading="lazy"></details>'
    explanation=ref.get('evidencia','')
    if name.startswith('ldec'):explanation+=' LDEC representa cobertura de observaciones de altimetría; no es un mapa de alturas.'
    if name.startswith('ldac'):explanation+=' LDAC pertenece a la familia de productos de albedo; la interpretación exacta y su escala requieren la etiqueta .LBL ausente. No usar como relieve.'
    if name=='ldem_64.tif':explanation+=' Es el recurso adecuado para desplazar una superficie 3D. Valores verticales en km según la documentación del producto NASA.'
    if dup:explanation=f'Duplicado exacto de {dup}. Coincidencia SHA-256 completa. Se conserva el original y se comparte la vista previa. '+explanation
    articles.append(f'''<article data-body="{esc(r['cuerpo'])}"><div class="information"><span class="tag">{esc(r['cuerpo'])} · {'Duplicado' if dup else esc(r['tipo'])}</span><h2>{esc(name)}</h2><p>{esc(explanation)}</p><dl>{''.join(f'<div><dt>{esc(k)}</dt><dd>{esc(v)}</dd></div>' for k,v in facts.items())}</dl><div class="links">{links}</div><details><summary>Metadatos y evidencia</summary><pre>{esc(json.dumps(r,ensure_ascii=False,indent=2))}</pre></details></div><figure><a href="{quote(r['preview'])}" aria-label="Ampliar vista de {esc(name)}"><img src="{quote(r['preview'])}" width="{w}" height="{h}" alt="Visualización derivada de {esc(name)}" {'fetchpriority="high"' if name=='ldem_64.tif' else 'loading="lazy"'}></a><figcaption>{esc(caption)}</figcaption>{extra}</figure></article>''')
page='''<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Luna y Marte · Inventario visual</title><style>
:root{color-scheme:light;--paper:#f4f1e9;--ink:#252d2a;--muted:#53615b;--line:#c6cec4;--accent:#225c49}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--accent);text-underline-offset:4px}a:hover{color:#102d23}button,select{font:inherit}button{cursor:pointer}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid #a25328;outline-offset:5px}::selection{background:#c6ddce}header,main,footer{max-width:1400px;margin:auto;padding:30px 5vw}header{border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px}header strong{font-weight:600}h1{font:clamp(2.8rem,6vw,5rem)/1.06 Georgia,serif;letter-spacing:-.035em;margin:28px 0 24px;max-width:900px}h2{font-size:1.35rem;line-height:1.3;margin:14px 0;overflow-wrap:anywhere}p{max-width:72ch} .intro{color:var(--muted);font-size:1.1rem}.status{padding:18px 0;border-block:1px solid var(--line);margin:30px 0;color:var(--muted)}search{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:24px 0 8px}search span{margin-right:12px}button{border:1px solid var(--line);border-radius:6px;padding:9px 18px;background:transparent;color:var(--ink)}button:hover{background:#e4e9df}button[aria-pressed="true"]{background:var(--accent);color:#fff;border-color:var(--accent)}#count{color:var(--muted);font-size:.9rem}article{display:grid;grid-template-columns:minmax(260px, .8fr) minmax(0,1.2fr);gap:45px;padding:44px 0;border-bottom:1px solid var(--line)}.tag{color:var(--accent);font-size:.85rem;font-weight:600}figure{margin:0;min-width:0}img{display:block;width:100%;height:auto;background:#e8e6dd}figure>a{display:block}figcaption,.legend{font-size:.85rem;color:var(--muted);margin:14px 0}dl{font-size:.9rem;font-variant-numeric:tabular-nums}dl>div{display:flex;justify-content:space-between;gap:15px;padding:7px 0;border-bottom:1px solid var(--line)}dt{color:var(--muted)}dd{margin:0;text-align:right}.links{display:flex;flex-wrap:wrap;gap:8px 20px;margin:22px 0}details{margin-top:20px}summary{cursor:pointer;color:var(--accent)}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.75rem;max-height:400px;overflow:auto;background:#e7ebe2;padding:16px}#empty{padding:50px 0;max-width:750px}#empty h2{font:2.6rem Georgia,serif}footer{color:var(--muted);font-size:.9rem}footer p{max-width:90ch}[hidden]{display:none!important}@media(max-width:760px){article{grid-template-columns:1fr;gap:24px}header{flex-direction:column;gap:8px}header,main,footer{padding-inline:6vw}h1{margin-top:20px}.intro{font-size:1rem}dl>div{gap:10px}search{gap:8px}button{padding:9px 12px}}
</style></head><body><header><strong>Archivo de superficies planetarias</strong><a href="inventario.json" download>Descargar inventario JSON</a></header><main><h1>Luna y Marte.<br>Los datos, a la vista.</h1><p class="intro">Explora los archivos de <code>datos/</code>, sus imágenes y su utilidad para construir relieve 3D. Cada clasificación incluye la evidencia disponible.</p><p class="status"><strong>4 archivos lunares</strong> (3 conjuntos únicos) · <strong>1 paquete 3D sin identificar</strong> · <strong>0 archivos confirmados de Marte</strong><br>Las vistas son conversiones de tus datos. Los colores representan valores, no fotografías de la superficie.</p><search aria-label="Filtrar por cuerpo celeste"><span>Mostrar</span><button type="button" data-filter="Todos" aria-pressed="true">Todo · 5</button><button type="button" data-filter="Luna" aria-pressed="false">Luna · 4</button><button type="button" data-filter="Marte" aria-pressed="false">Marte · 0</button><button type="button" data-filter="Sin determinar" aria-pressed="false">Sin determinar · 1</button></search><p id="count" role="status">5 archivos visibles</p><section aria-label="Archivos clasificados">ARTICLES</section><section id="empty" hidden><h2>Marte aún no está identificado.</h2><p>No se encontraron archivos con evidencia de procedencia marciana. El ZIP no contiene un sistema de referencia ni el nombre del cuerpo celeste; se mantiene en «Sin determinar» hasta disponer de su fuente.</p><button type="button" id="reset">Ver todos los archivos</button></section></main><footer><p>Los originales no se han modificado. La ausencia de etiquetas PDS impide validar las unidades y valores NoData de los JP2.</p><p>Referencias para interpretar los productos: <a href="https://svs.gsfc.nasa.gov/4720/">NASA · CGI Moon Kit</a>, <a href="https://pgda.gsfc.nasa.gov/products/90">NASA · LOLA y mapas de conteo</a> y <a href="https://ode.rsl.wustl.edu/Mars/pagehelp/Content/Missions_Instruments/Lunar%20Reconnaissance%20Orbiter%20%28LRO%29/LOLA/GDR/GDRDAM.htm">PDS · productos de albedo LOLA</a>. El segmento «Mars» de una URL del catálogo no identifica el cuerpo del producto.</p></footer><script>
const buttons=[...document.querySelectorAll('[data-filter]')],articles=[...document.querySelectorAll('article')];function filter(value){let count=0;for(const a of articles){a.hidden=value!=='Todos'&&a.dataset.body!==value;if(!a.hidden)count++}for(const b of buttons)b.setAttribute('aria-pressed',String(b.dataset.filter===value));document.getElementById('count').textContent=`${count} archivos visibles`;document.getElementById('empty').hidden=count!==0}for(const b of buttons)b.addEventListener('click',()=>filter(b.dataset.filter));document.getElementById('reset').addEventListener('click',()=>{filter('Todos');buttons[0].focus()});
</script></body></html>'''.replace('ARTICLES','\n'.join(articles))
(out/'inventario.html').write_text(page,encoding='utf-8')
print('HTML creado')
